fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let n = a.len();

    // Choose a split point that guarantees, when n > 1:
    // 0 < mid < n, so both parts are strictly shorter than the original.
    let mid = if n <= 1 { n } else { n / 2 };

    // split_off keeps order:
    // - `left` becomes a[0..mid]
    // - returned `right` is a[mid..n]
    let mut left = a;
    let right = left.split_off(mid);
    (left, right)
}